ge space.","location_description":"The premises is location on a ver busy spot on Berwick Street in the heart of Soho with very high footfall every day of the week at all times. Transport links are excellent with Oxford Circus and Piccadilly Tube stations being a short walking distance from the premises.","key_features":["Fully Fitted Turnkey Operation","High Footfall Location","Outside Seating","Protected Lease","Light Kitchen Extraction"],"sections":[{"title":"Description","content":"A lovely little cosy restaurant fully fitted out with circa 36 covers divided equally over the ground floor and basement. There is a small kitchen is the basement with light ventless extraction together with WC facilities and plenty of storage space."},{"title":"Tenure","content":"Assignment of the existing FRI lease which expires in December 2030, and is contracted inside the security provisions of the Landlord & Tenant Act 1954."},{"title":"Rent","content":"£48,000 per annum exclusive."},{"title":"Premium","content":"On Application."},{"title":"VAT","content":"All prices quoted may be subject to VAT if applicable."},{"title":"Planning/Licence","content":"The premises benefit from E class planning use with a premises licence which allows for sale of alcohol with table meals with the following days & hours. Monday to Saturday: 11:00 to 23:30 -  Sunday: 12:00 to 22:30."},{"title":"Confidentiality","content":"This letting is highly confidential and under no circumstances should a direct approach be made to staff as they are unaware of an impending sale."},{"title":"Holding Deposit","content":"A holding deposit will be required to secure the property which will allow a period of exclusivity and will be held in the CDG Leisure client account."}],"agent_name":"Salvatore Di Natale","agent_email":"salvatore@cdgleisure.com","agent_phone":"07989 471288","agent_photo":"https://as-images.imgix.net/0c80fd529148bd3060556967a6287ef8-salv%20pic%20for%20property%20details.jpg","images":[{"url":"https://as-images.imgix.net/37486155ae7e13cf21e24a83f128377d-italian-pasta.jpg","alt":"Berwick Street, Soho, Restaurant Lease Assignment - Italian Pasta.jpg","source_url":"https://as-images.imgix.net/37486155ae7e13cf21e24a83f128377d-italian-pasta.jpg?mark=https%3A%2F%2Fas-images.imgix.net%2F5fcc3b7220158f27f85989bfa2708db8-screenshot-2024-06-19-at-14-54-05-removebg-preview.png&mark-alpha=90&mark-scale=30&mark-align=right,bottom"}],"brochure_url":"https://s3-eu-west-1.amazonaws.com/agents-society-assets-files/pdf/218773d50f59fa70f5458876b1030e86.pdf"}]$cdg$::jsonb;
begin
  select id into demo_agency from public.agencies where name = 'CDG demo' limit 1;
  if demo_agency is null then raise exception 'Demo agency "CDG demo" not found.'; end if;

  select array_agg(user_id order by user_id) into member_ids
    from public.agency_members where agency_id = demo_agency;
  if member_ids is null or array_length(member_ids, 1) = 0 then
    raise exception 'Demo agency has no members.';
  end if;

  for rec in select * from jsonb_array_elements(payload) loop
    i := i + 1;
    select p.id into lead
      from public.profiles p
      join public.agency_members am on am.user_id = p.id
     where am.agency_id = demo_agency and p.full_name = rec->>'agent_name'
     limit 1;
    if lead is null then lead := member_ids[1 + (i % array_length(member_ids, 1))]; end if;
    insert into public.disposals (
      agency_id, source, source_ref, source_url, status, source_updated_at,
      title, summary, address_line, area, city, postcode, lat, lng,
      property_type, use_class, disposal_type, to_let, for_sale,
      rent_pa, rent_raw, rent_period, premium, premium_raw, guide_price, price_qualifier,
      vat_applicable, rateable_value, business_rates, service_charge, estate_charge, parking_charge,
      tenure_raw, lease_term_years, lease_expiry, rent_review_basis, next_rent_review, inside_1954_act,
      size_sqft, size_sqm, covers_internal, covers_external, floors,
      licensing_notes, fit_out_state, epc_rating,
      description, location_description, key_features, sections,
      agent_name, agent_email, agent_phone, agent_photo,
      images, brochure_url,
      lead_agent_id, created_by
    ) values (
      demo_agency,
      coalesce(rec->>'source', 'cdg'), rec->>'source_ref', rec->>'source_url', rec->>'status',
      (rec->>'source_updated_at')::timestamptz,
      rec->>'title', rec->>'summary', rec->>'address_line', rec->>'area', rec->>'city',
      rec->>'postcode', (rec->>'lat')::double precision, (rec->>'lng')::double precision,
      rec->>'property_type', rec->>'use_class', rec->>'disposal_type',
      (rec->>'to_let')::boolean, (rec->>'for_sale')::boolean,
      (rec->>'rent_pa')::numeric, rec->>'rent_raw', rec->>'rent_period',
      (rec->>'premium')::numeric, rec->>'premium_raw', (rec->>'guide_price')::numeric,
      rec->>'price_qualifier',
      (rec->>'vat_applicable')::boolean, (rec->>'rateable_value')::numeric,
      (rec->>'business_rates')::numeric, (rec->>'service_charge')::numeric,
      (rec->>'estate_charge')::numeric, (rec->>'parking_charge')::numeric,
      rec->>'tenure_raw', (rec->>'lease_term_years')::int, (rec->>'lease_expiry')::date,
      rec->>'rent_review_basis', (rec->>'next_rent_review')::int, (rec->>'inside_1954_act')::boolean,
      (rec->>'size_sqft')::numeric, (rec->>'size_sqm')::numeric,
      (rec->>'covers_internal')::int, (rec->>'covers_external')::int,
      coalesce(rec->'floors', '[]'::jsonb),
      rec->>'licensing_notes', rec->>'fit_out_state', rec->>'epc_rating',
      rec->>'description', rec->>'location_description',
      coalesce(array(select jsonb_array_elements_text(rec->'key_features')), '{}'::text[]),
      coalesce(rec->'sections', '[]'::jsonb),
      rec->>'agent_name', rec->>'agent_email', rec->>'agent_phone', rec->>'agent_photo',
      coalesce(rec->'images', '[]'::jsonb), rec->>'brochure_url',
      lead, lead
    );
  end loop;
end $$;
